    myths: [
      { myth: "Es gibt eine endgültige Liste der besten Filme.", fact: "Der BFI führt zwei verschiedene Umfragen (Kritiker, Regisseure); die Rangfolge verändert sich von Ausgabe zu Ausgabe. [1]" },
    ],
    mistakes: ["Nur Filme der obersten Plätze sehen und Epochen auslassen (Vorschlag).", "Listen als objektive Wahrheit statt als Expertenmeinung lesen. [1]"],
